//! MariaDB and MongoDB as extra services from the Versions page. Both listen on 127.0.0.1 only;
//! MariaDB on 3307 so it runs beside MySQL (3306), MongoDB on its usual 27017.

use std::io::{Read, Write};
use std::net::TcpStream;
use std::path::Path;
use std::time::Duration;

pub const MARIADB_PORT: u16 = 3307;
pub const MONGODB_PORT: u16 = 27017;

/// MariaDB's settings file, written by NexDB like MySQL's.
pub fn mariadb_ini(base: &Path, data: &Path, log: &Path) -> String {
    let p = crate::configure::conf_path;
    format!(
        "# Generated by NexDB. Changes here are overwritten.\n[mysqld]\nbasedir=\"{}\"\ndatadir=\"{}\"\nport={MARIADB_PORT}\n# Only this PC can connect.\nbind-address=127.0.0.1\ncharacter-set-server=utf8mb4\ncollation-server=utf8mb4_unicode_ci\nlog-error=\"{}\"\n\n[client]\nport={MARIADB_PORT}\ndefault-character-set=utf8mb4\n",
        p(base),
        p(data),
        p(log),
    )
}

/// Writes MariaDB's settings and, the first time, an empty data folder. Root has no password,
/// like NexDB's MySQL, and only this PC can connect.
pub fn setup_mariadb(base: &Path, root: &Path) -> Result<(), String> {
    let data = root.join("data").join("mariadb");
    let ini = root.join("etc").join("mariadb").join("my.ini");
    crate::configure::write_file(&ini, &mariadb_ini(base, &data, &root.join("logs").join("mariadb_error.log")))?;
    if data.join("mysql").is_dir() {
        return Ok(());
    }
    // A half-made folder from an earlier try is cleared first.
    if data.exists() {
        std::fs::remove_dir_all(&data).map_err(|e| format!("Couldn't clear MariaDB's data folder: {e}"))?;
    }
    // mariadb-install-db makes the data folder itself, but not the folders above it.
    for dir in [root.join("logs"), root.join("data")] {
        std::fs::create_dir_all(&dir).map_err(|e| format!("Couldn't create {}: {e}", dir.display()))?;
    }
    let datadir = format!("--datadir={}", data.display());
    let port = format!("--port={MARIADB_PORT}");
    let out = crate::configure::run_quiet(
        &base.join("bin").join("mariadb-install-db.exe"),
        &[&datadir, &port],
        Duration::from_secs(180),
    )
    .map_err(|e| format!("Couldn't set up MariaDB's data folder: {e}"))?;
    if !out.success || !data.join("mysql").is_dir() {
        return Err(format!("MariaDB couldn't set up its data folder: {}", out.text.trim()));
    }
    // mariadb-install-db leaves its own my.ini in the data folder; NexDB's in etc is the one used.
    let _ = std::fs::remove_file(data.join("my.ini"));
    Ok(())
}

pub fn setup_mongodb(root: &Path) -> Result<(), String> {
    std::fs::create_dir_all(root.join("data").join("mongodb")).map_err(|e| format!("Couldn't create MongoDB's data folder: {e}"))
}

/// A BSON document with string and int32 fields, enough for an admin command.
fn bson(fields: &[(&str, Field)]) -> Vec<u8> {
    let mut body = Vec::new();
    for (name, value) in fields {
        match value {
            Field::Int(n) => {
                body.push(0x10);
                body.extend_from_slice(name.as_bytes());
                body.push(0);
                body.extend_from_slice(&n.to_le_bytes());
            }
            Field::Str(s) => {
                body.push(0x02);
                body.extend_from_slice(name.as_bytes());
                body.push(0);
                body.extend_from_slice(&((s.len() + 1) as i32).to_le_bytes());
                body.extend_from_slice(s.as_bytes());
                body.push(0);
            }
        }
    }
    body.push(0);
    let mut doc = ((body.len() + 4) as i32).to_le_bytes().to_vec();
    doc.extend(body);
    doc
}

enum Field {
    Int(i32),
    Str(&'static str),
}

/// An OP_MSG with one command document.
fn op_msg(doc: &[u8]) -> Vec<u8> {
    let len = 16 + 4 + 1 + doc.len();
    let mut msg = Vec::with_capacity(len);
    msg.extend_from_slice(&(len as i32).to_le_bytes());
    msg.extend_from_slice(&1i32.to_le_bytes()); // requestID
    msg.extend_from_slice(&0i32.to_le_bytes()); // responseTo
    msg.extend_from_slice(&2013i32.to_le_bytes()); // OP_MSG
    msg.extend_from_slice(&0u32.to_le_bytes()); // flagBits
    msg.push(0); // section kind 0: the body
    msg.extend_from_slice(doc);
    msg
}

/// Asks mongod to shut down cleanly ({shutdown: 1} on admin), allowed from this PC while the
/// server has no users. Returns true when the request was sent.
pub fn mongodb_shutdown(port: u16) -> bool {
    let Ok(mut s) = TcpStream::connect_timeout(&([127, 0, 0, 1], port).into(), Duration::from_secs(3)) else {
        return false;
    };
    let _ = s.set_read_timeout(Some(Duration::from_secs(5)));
    let msg = op_msg(&bson(&[("shutdown", Field::Int(1)), ("$db", Field::Str("admin"))]));
    if s.write_all(&msg).is_err() {
        return false;
    }
    // The server closes the connection as it goes down; any reply (or none) is fine.
    let mut buf = [0u8; 512];
    let _ = s.read(&mut buf);
    true
}

/// Whether something answers MongoDB's `ping` on the port (used by the tests).
#[cfg(test)]
pub fn mongodb_ping(port: u16) -> bool {
    let Ok(mut s) = TcpStream::connect_timeout(&([127, 0, 0, 1], port).into(), Duration::from_secs(3)) else {
        return false;
    };
    let _ = s.set_read_timeout(Some(Duration::from_secs(5)));
    if s.write_all(&op_msg(&bson(&[("ping", Field::Int(1)), ("$db", Field::Str("admin"))]))).is_err() {
        return false;
    }
    let mut buf = vec![0u8; 1024];
    let n = s.read(&mut buf).unwrap_or(0);
    // A reply is OP_MSG back with {ok: 1.0}: the field name "ok" followed by a double 1.0.
    n > 21 && buf[12..16] == 2013i32.to_le_bytes() && buf[..n].windows(11).any(|w| w == b"ok\0\0\0\0\0\0\0\xf0\x3f")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bson_and_op_msg_are_well_formed() {
        let doc = bson(&[("ping", Field::Int(1)), ("$db", Field::Str("admin"))]);
        // 4 len + (1+5+4) + (1+4+4+6) + 1 = 30
        assert_eq!(doc.len(), 30);
        assert_eq!(i32::from_le_bytes(doc[..4].try_into().unwrap()), 30);
        let msg = op_msg(&doc);
        assert_eq!(i32::from_le_bytes(msg[..4].try_into().unwrap()) as usize, msg.len());
        assert_eq!(&msg[12..16], &2013i32.to_le_bytes());
    }

    #[test]
    fn mariadb_ini_listens_on_this_pc_beside_mysql() {
        let ini = mariadb_ini(Path::new(r"C:\NexDB\bin\mariadb\mariadb-12.3.3"), Path::new(r"C:\NexDB\data\mariadb"), Path::new(r"C:\NexDB\logs\mariadb_error.log"));
        assert!(ini.contains("port=3307") && ini.contains("bind-address=127.0.0.1"));
        assert!(ini.contains("datadir=\"C:/NexDB/data/mariadb\""), "{ini}");
    }

    /// Downloads MariaDB from the catalog, sets up its data folder, starts it on a spare port,
    /// runs a query and stops it with its shutdown event.
    /// `cargo test real_mariadb -- --ignored --nocapture`
    #[test]
    #[ignore]
    fn real_mariadb() {
        use crate::supervisor::{ServiceSpec, StopMethod, Supervisor};
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        let tool = crate::catalog::bundled().tools.mariadb.expect("catalog has MariaDB");
        let base = root.join("bin").join("mariadb").join(format!("mariadb-{}", tool.version));
        tauri::async_runtime::block_on(crate::installer::install_archive(&tool.download, root, &base, "get-mariadb", &|_| {}))
            .unwrap();
        setup_mariadb(&base, root).unwrap();
        // A spare port, so a MariaDB already on 3307 doesn't get in the way.
        let ini = root.join("etc").join("mariadb").join("my.ini");
        let text = std::fs::read_to_string(&ini).unwrap().replace("port=3307", "port=3317");
        std::fs::write(&ini, text).unwrap();
        let sup = Supervisor::new(vec![ServiceSpec {
            id: "mariadb".into(),
            name: "MariaDB".into(),
            version: Some(tool.version.clone()),
            exe: base.join("bin").join("mariadbd.exe"),
            args: vec![format!("--defaults-file={}", ini.display()), "--console".into()],
            cwd: base.clone(),
            port: 3317,
            managed: true,
            stop: StopMethod::MysqlEvent,
            log: root.join("logs").join("mariadb_error.log"),
        }]);
        sup.start("mariadb").unwrap();
        let out = crate::configure::run_quiet(
            &base.join("bin").join("mariadb.exe"),
            &["-h", "127.0.0.1", "-P", "3317", "-u", "root", "-N", "-e", "SELECT VERSION();"],
            Duration::from_secs(30),
        )
        .unwrap();
        println!("{}", out.text);
        assert!(out.success && out.text.contains(&tool.version), "{}", out.text);
        sup.stop("mariadb").unwrap();
        assert!(!sup.status().iter().any(|s| s.state == crate::supervisor::State::Running));
    }

    /// Downloads MongoDB from the catalog (about 1 GB), starts it on a spare port, pings it and
    /// shuts it down with the shutdown command. `cargo test real_mongodb -- --ignored --nocapture`
    #[test]
    #[ignore]
    fn real_mongodb() {
        use crate::supervisor::{ServiceSpec, StopMethod, Supervisor};
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        let tool = crate::catalog::bundled().tools.mongodb.expect("catalog has MongoDB");
        let base = root.join("bin").join("mongodb").join(format!("mongodb-{}", tool.version));
        tauri::async_runtime::block_on(crate::installer::install_archive(&tool.download, root, &base, "get-mongodb", &|_| {}))
            .unwrap();
        setup_mongodb(root).unwrap();
        let port = 27117u16;
        let sup = Supervisor::new(vec![ServiceSpec {
            id: "mongodb".into(),
            name: "MongoDB".into(),
            version: Some(tool.version.clone()),
            exe: base.join("bin").join("mongod.exe"),
            args: vec![
                "--dbpath".into(),
                root.join("data").join("mongodb").display().to_string(),
                "--port".into(),
                port.to_string(),
                "--bind_ip".into(),
                "127.0.0.1".into(),
            ],
            cwd: base.clone(),
            port,
            managed: true,
            stop: StopMethod::MongoShutdown,
            log: root.join("logs").join("mongodb.log"),
        }]);
        sup.start("mongodb").unwrap();
        assert!(mongodb_ping(port), "mongod answers ping");
        sup.stop("mongodb").unwrap();
        assert!(!mongodb_ping(port));
    }
}
